const body = $input.first().json.body ?? $input.first().json;
const env = String(body.env || 'unknown').toLowerCase().trim();
const userId = body.user_id;
if (userId === undefined || userId === null || userId === '') {
  return [{ json: { skip: true, reason: 'missing user_id' } }];
}
const event = body.event === 'write' ? 'write' : 'open';
const key = `${env}:${userId}`;
const at = body.at || new Date().toISOString();
const base = {
  key,
  env,
  user_id: userId,
  username: body.username || '',
  company_id: body.company_id ?? null,
  company_code: body.company_code ?? null,
  updated_at: at,
};
if (event === 'open') {
  return [{ json: {
    ...base,
    patch: {
      last_opened_menu: body.menu_slug || body.menu_path || '',
      last_opened_path: body.menu_path || '',
      last_opened_at: at,
      username: base.username,
      company_id: base.company_id,
      company_code: base.company_code,
    }
  }}];
}
return [{ json: {
  ...base,
  patch: {
    last_write_menu: body.menu_slug || body.menu_path || '',
    last_write_path: body.menu_path || '',
    last_write_at: at,
    last_write_method: body.method || '',
    username: base.username,
    company_id: base.company_id,
    company_code: base.company_code,
  }
}}];

const incoming = $('Normalize Payload').first().json;
const existing = $input.first().json || {};
const prev = existing.json ?? existing;
const merged = {
  key: incoming.key,
  env: incoming.env,
  user_id: incoming.user_id,
  username: incoming.patch.username || prev.username || '',
  company_id: incoming.patch.company_id ?? prev.company_id ?? null,
  company_code: incoming.patch.company_code ?? prev.company_code ?? null,
  last_opened_menu: prev.last_opened_menu || null,
  last_opened_path: prev.last_opened_path || null,
  last_opened_at: prev.last_opened_at || null,
  last_write_menu: prev.last_write_menu || null,
  last_write_path: prev.last_write_path || null,
  last_write_at: prev.last_write_at || null,
  last_write_method: prev.last_write_method || null,
  updated_at: incoming.updated_at,
  ...incoming.patch,
};
return [{ json: merged }];

const rows = $input.all().map((i) => i.json).filter((r) => r && (r.env || r.user_id));
rows.sort((a, b) => String(b.updated_at || '').localeCompare(String(a.updated_at || '')));
const secret = $env.USER_ACTIVITY_EXPORT_SECRET || '';
const q = $('Webhook Export').first().json.query || {};
if (secret && q.token !== secret) {
  return [{ json: { error: 'unauthorized', users: [] } }];
}
return [{ json: {
  generated_at: new Date().toISOString(),
  count: rows.length,
  users: rows,
}}];
